@mcp.tool()
def catalog_create_categories(
    taxonomy: str,
    categories: list,
) -> dict:
    """Create taxonomy terms (categories) for the catalog"""
    _tax_map = {"category": "categories", "post_tag": "tags", "product_cat": "product_categories"}
    rest_base = _tax_map.get(taxonomy, taxonomy)
    wp = _wp()
    results = []
    for cat in (categories or []):
        body = cat if isinstance(cat, dict) else {"name": str(cat)}
        try:
            results.append(wp.post(f"/wp/v2/{rest_base}", json=body))
        except Exception as exc:
            results.append({"error": str(exc)})
    return {"created": results, "count": len(results)}

