@mcp.tool()
def catalog_set_featured_items(
    post_type: str,
    item_ids: list,
    featured: bool = True,
) -> dict:
    """Mark specific catalog items as featured"""
    _rest_map = {"post": "posts", "page": "pages"}
    rest_base = _rest_map.get(post_type, post_type)
    wp = _wp()
    results = []
    for item_id in (item_ids or []):
        try:
            results.append(wp.post(f"/wp/v2/{rest_base}/{item_id}", json={"sticky": featured}))
        except Exception as exc:
            results.append({"id": item_id, "error": str(exc)})
    return {"updated": results, "count": len(results)}

