@mcp.tool()
def woo_update_store_settings(
    group: str,
    settings: list,
) -> dict:
    """Update WooCommerce store settings"""
    updated = []
    for setting in settings:
        setting_id = setting.get("id")
        if not setting_id:
            raise ValueError("Each setting must include an 'id'.")
        body = {k: v for k, v in setting.items() if k != "id"}
        updated.append(_wp().woo_put(f"/settings/{group}/{setting_id}", json=body))
    return {"updated": updated, "count": len(updated)}

