@mcp.tool()
def wc_configure_paypal_gateway(
    enabled: str = None,
    title: str = None,
    description: str = None,
    email: str = None,
    testmode: str = None,
    debug: str = None,
    ipn_notification: str = None,
    receiver_email: str = None,
    identity_token: str = None,
    invoice_prefix: str = None,
    send_shipping: str = None,
    address_override: str = None,
    paymentaction: str = None,
    page_style: str = None,
    image_url: str = None,
    api_username: str = None,
    api_password: str = None,
    api_signature: str = None,
    sandbox_api_username: str = None,
    sandbox_api_password: str = None,
    sandbox_api_signature: str = None,
) -> dict:
    """Configure the PayPal Standard payment gateway"""
    params = {}
    if enabled is not None: params["enabled"] = enabled
    if title is not None: params["title"] = title
    if description is not None: params["description"] = description
    if email is not None: params["email"] = email
    if testmode is not None: params["testmode"] = testmode
    if debug is not None: params["debug"] = debug
    if ipn_notification is not None: params["ipn_notification"] = ipn_notification
    if receiver_email is not None: params["receiver_email"] = receiver_email
    if identity_token is not None: params["identity_token"] = identity_token
    if invoice_prefix is not None: params["invoice_prefix"] = invoice_prefix
    if send_shipping is not None: params["send_shipping"] = send_shipping
    if address_override is not None: params["address_override"] = address_override
    if paymentaction is not None: params["paymentaction"] = paymentaction
    if page_style is not None: params["page_style"] = page_style
    if image_url is not None: params["image_url"] = image_url
    if api_username is not None: params["api_username"] = api_username
    if api_password is not None: params["api_password"] = api_password
    if api_signature is not None: params["api_signature"] = api_signature
    if sandbox_api_username is not None: params["sandbox_api_username"] = sandbox_api_username
    if sandbox_api_password is not None: params["sandbox_api_password"] = sandbox_api_password
    if sandbox_api_signature is not None: params["sandbox_api_signature"] = sandbox_api_signature
    return _wp().woo_get("/payment_gateways", params=params)

